4XyGCMOB.css:
transform-origin: center;
transition:
  scale {transition.duration-sweep} {ease.out},
  opacity {transition.duration-sweep} {ease.out};

@starting-style {
  scale: 1 0;
  opacity: 0;
}

*:hover > & {
  scale: 1 1.25;
}

&[data-state="removed"] {
  scale: 1 0;
  opacity: 0;
  transition-duration: {transition.duration-pop-exit};
  transition-timing-function: {ease.in};
}

@media (prefers-reduced-motion: reduce) {
  transition-property: opacity;

  @starting-style {
    scale: 1;
  }
}

